  const view = toToolView(tool, loans);

  assert.deepEqual(view, {
    id: "1",
    name: "Hammer",
    condition: "gut",
    status: "borrowed",
    loan: { borrower: "Alex", borrowedAt: "2026-08-08T10:00:00.000Z" },
  });
});

